use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl TokenKind { pub fn lit (kind : LitKind , symbol : Symbol , suffix : Option < Symbol >) -> TokenKind { Literal (Lit :: new (kind , symbol , suffix)) } # [doc = " An approximation to proc-macro-style single-character operators used by"] # [doc = " rustc parser. If the operator token can be broken into two tokens, the"] # [doc = " first of which has `n` (1 or 2) chars, then this function performs that"] # [doc = " operation, otherwise it returns `None`."] pub fn break_two_token_op (& self , n : u32) -> Option < (TokenKind , TokenKind) > { assert ! (n == 1 || n == 2) ; Some (match (self , n) { (Le , 1) => (Lt , Eq) , (EqEq , 1) => (Eq , Eq) , (Ne , 1) => (Bang , Eq) , (Ge , 1) => (Gt , Eq) , (AndAnd , 1) => (And , And) , (OrOr , 1) => (Or , Or) , (Shl , 1) => (Lt , Lt) , (Shr , 1) => (Gt , Gt) , (PlusEq , 1) => (Plus , Eq) , (MinusEq , 1) => (Minus , Eq) , (StarEq , 1) => (Star , Eq) , (SlashEq , 1) => (Slash , Eq) , (PercentEq , 1) => (Percent , Eq) , (CaretEq , 1) => (Caret , Eq) , (AndEq , 1) => (And , Eq) , (OrEq , 1) => (Or , Eq) , (ShlEq , 1) => (Lt , Le) , (ShlEq , 2) => (Shl , Eq) , (ShrEq , 1) => (Gt , Ge) , (ShrEq , 2) => (Shr , Eq) , (DotDot , 1) => (Dot , Dot) , (DotDotDot , 1) => (Dot , DotDot) , (DotDotDot , 2) => (DotDot , Dot) , (DotDotEq , 2) => (DotDot , Eq) , (PathSep , 1) => (Colon , Colon) , (RArrow , 1) => (Minus , Gt) , (LArrow , 1) => (Lt , Minus) , (FatArrow , 1) => (Eq , Gt) , _ => return None , }) } # [doc = " Returns tokens that are likely to be typed accidentally instead of the current token."] # [doc = " Enables better error recovery when the wrong token is found."] pub fn similar_tokens (& self) -> & [TokenKind] { match self { Comma => & [Dot , Lt , Semi] , Semi => & [Colon , Comma] , Colon => & [Semi] , FatArrow => & [Eq , RArrow , Ge , Gt] , _ => & [] , } } pub fn should_end_const_arg (& self) -> bool { matches ! (self , Gt | Ge | Shr | ShrEq) } pub fn is_delim (& self) -> bool { self . open_delim () . is_some () || self . close_delim () . is_some () } pub fn open_delim (& self) -> Option < Delimiter > { match * self { OpenParen => Some (Delimiter :: Parenthesis) , OpenBrace => Some (Delimiter :: Brace) , OpenBracket => Some (Delimiter :: Bracket) , OpenInvisible (origin) => Some (Delimiter :: Invisible (origin)) , _ => None , } } pub fn close_delim (& self) -> Option < Delimiter > { match * self { CloseParen => Some (Delimiter :: Parenthesis) , CloseBrace => Some (Delimiter :: Brace) , CloseBracket => Some (Delimiter :: Bracket) , CloseInvisible (origin) => Some (Delimiter :: Invisible (origin)) , _ => None , } } pub fn is_close_delim_or_eof (& self) -> bool { match self { CloseParen | CloseBrace | CloseBracket | CloseInvisible (_) | Eof => true , _ => false , } } }